  "status": "SUPPORTED",
  "claim": {
    "component_id": "C017",
    "value": "Each evidence item should be assessed against every candidate explanation as consistent, inconsistent or unknown.",
    "scope": "The prescribed comparison includes all listed alternatives and permits unknown assessments.",
    "provenance": {
      "refs": [
        {
          "source_id": "P008",
          "role": "SUPPORT"
        }
      ],
      "support_status": "SUFFICIENT",
      "rationale": "P008 directly specifies assessment of every evidence item against every explanation using these three categories."
    }
  },
  "signal_basis": {
    "component_id": "C017_signal_basis",
    "value": "Construct an evidence-by-hypothesis matrix recording consistency, inconsistency or uncertainty for each pairing, together with reliability and diagnostic value, to identify comparative patterns across explanations.",
    "scope": "The listed, potentially coexisting explanations; comparative patterns rather than an isolated suspicious trace.",
    "provenance": {
      "refs": [
        {
          "source_id": "P008",
          "role": "SUPPORT"
        },
        {
          "source_id": "P017",
          "role": "SUPPORT"
        },
        {
          "source_id": "P002",
          "role": "CONTEXT"
        }
      ],
      "support_status": "SUFFICIENT",
      "rationale": "P008 supplies the assessment operation and evidence qualifications; P017 supplies the comparative focus. P002 identifies the candidate set and its potentially coexisting members."
    }
  },
  "stated_empirical_relation": {
    "component_id": "C017_stated_empirical_relation",
    "value": "NOT_APPLICABLE",
    "scope": "NOT_APPLICABLE",
    "provenance": {
      "refs": [],
      "support_status": "SUFFICIENT",
      "rationale": "This supported procedural claim requires no unresolved empirical relation."
    }
  },
  "rationale": "Assessing each item against every candidate is warranted by the prescribed comparative operation: it makes differential consistency visible while allowing unknown assessments where evidence cannot decide. The claim prescribes a comparison procedure and does not assert that its categories establish a cause.",
  "uncertainty": "Evidence reliability and judgment can affect the comparison's conclusions without undermining this bounded procedural claim.",
  "anomalies": []
}
